CREATE POLICY "Members read site assets" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'site-assets');
CREATE POLICY "Staff upload site assets" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'site-assets' AND public.is_staff(auth.uid()));
CREATE POLICY "Staff update site assets" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'site-assets' AND public.is_staff(auth.uid())) WITH CHECK (bucket_id = 'site-assets' AND public.is_staff(auth.uid()));
CREATE POLICY "Staff delete site assets" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'site-assets' AND public.is_staff(auth.uid()));